WITH valid_stores AS (SELECT * FROM stores WHERE opened_date >= '2025-07-01'), stores_stats AS (SELECT city, DATE_TRUNC('MONTH', opened_date) AS opened_month, MAX(sqft) - MIN(sqft) AS sqft_range, SUM(CASE WHEN region = 'South' THEN 1 ELSE 0 END) AS south_count FROM valid_stores GROUP BY city, DATE_TRUNC('MONTH', opened_date)) SELECT city, opened_month, sqft_range, south_count FROM stores_stats ORDER BY south_count DESC, sqft_range
